apiVersion: v1
kind: Secret
metadata:
  name: registry-secret
  namespace: default
type: kubernetes.io/dockerconfigjson
data:
  .dockerconfigjson: |
    {
      "auths": {
        "registry:5000/private": {
          "auth": "benchmark:benchmark-pass"
        }
      }
    }
EOF"}

